/*
 * Generate the three cake-block sounds.
 *
 *     node tools/make-cake-sfx.js
 *
 * Writes assets/fall.mp3, assets/land.mp3 and assets/swing.mp3.
 *
 * These three have to work as a SEQUENCE, because that is how the player hears
 * them: the block creaks on the rope, whooshes down, then lands. So they are
 * generated by one tool and voiced apart from each other on purpose —
 *
 *   swing  a dry rope creak, no pitch centre to speak of, held quiet
 *   fall   air, band sweeping UP as the cake accelerates, no attack at all
 *   land   the only one with a transient, and the only one with low end
 *
 * The existing drop.mp3 / drop-perfect.mp3 keep doing what they always did:
 * they are the SCORING chime for a landing. `land` is the physical thud under
 * them, which is why it is duller and shorter than either.
 */
const {
  lerp, clamp01, noise, lowpass, resonator, fadeEnds, normalise, write, render
} = require('./sfx-lib')

/* ---------------------------------------------------------------- fall -----
 * A falling cake makes no sound of its own; what sells the drop is air. The
 * band centre sweeps 520 Hz -> 2100 Hz over the clip and the level ramps in
 * from silence, so the ear reads acceleration rather than a burst of hiss.
 *
 * No attack transient on purpose. The player has just tapped, and the tap
 * already has click.mp3 on it — a second attack 30 ms later sounds like a
 * double-click, not like a release.
 */
const FALL_MS = 400
{
  const rnd = noise(0x2545f491)
  const band = resonator(1.6)
  const air = resonator(0.9)
  const lp = lowpass()
  const samples = render(FALL_MS, (t, u) => {
    const n = rnd()
    // Two bands: a broad one that carries the sweep, and a lower wider one so
    // the sweep has something to move against and does not sound like a filter
    // being turned.
    const f = lerp(520, 2100, u ** 1.35)
    const swept = band(n, f)
    const body = air(n, lerp(300, 620, u))
    // Level in on a curve, then duck the last 15%: the landing thud lands into
    // that gap, and a whoosh still at full tilt underneath it muddies the hit.
    const swell = (u ** 1.6) * (1 - (clamp01((u - 0.85) / 0.15) * 0.55))
    const v = lp((swept * 1.5) + (body * 0.9), 0.55) * swell
    return Math.tanh(v * 2.2) * fadeEnds(u, 8, 45, FALL_MS)
  })
  write('fall.mp3', normalise(samples, 0.82), 96)
}

/* ---------------------------------------------------------------- land -----
 * Cake on cake, not brick on brick. Three parts:
 *
 *   1. A low thump gliding 132 -> 62 Hz. The glide is what makes it soft; a
 *      fixed low sine is a kick drum.
 *   2. A short mid "pat" — the two slabs meeting.
 *   3. A wet noise splat around 1.5 kHz, decaying fast, for the cream squeezing
 *      out along the seam. This is the part that stops it sounding like wood,
 *      and it is the sound the cream-splash animation is drawn to.
 */
const LAND_MS = 260
{
  const rnd = noise(0x85ebca6b)
  const wet = resonator(1.1)
  const pat = resonator(1.4)
  const lp = lowpass()
  let ph = 0
  const samples = render(LAND_MS, (t, u) => {
    const f = lerp(132, 62, clamp01(t / 0.09) ** 0.6)
    ph += (Math.PI * 2 * f) / 44100
    const thump = Math.sin(ph) * Math.exp(-t * 21)

    const n = rnd()
    const splat = wet(n, lerp(1700, 900, clamp01(t / 0.05))) * Math.exp(-t * 58) * 2.4
    const body = pat(n, 380) * Math.exp(-t * 34) * 1.3

    const v = (thump * 1.15) + splat + body
    // Gentle lowpass: nothing about a cake landing should be crisp.
    return Math.tanh(lp(v, 0.62) * 1.5) * fadeEnds(u, 1.2, 40, LAND_MS)
  })
  write('land.mp3', normalise(samples, 0.94), 128)
}

/* --------------------------------------------------------------- swing -----
 * The rope taking the weight. Voiced once per swing extreme — twice a cycle —
 * so it has to be short enough not to overlap itself at the fastest hook speed
 * and characterless enough to bear repeating for a whole run.
 *
 * A creak is a narrow resonance whose amplitude STUTTERS: rope fibres slipping
 * against each other, not sliding smoothly. That stutter is the flutter term
 * below; without it this is just a filtered hiss.
 */
const SWING_MS = 300
{
  const rnd = noise(0xc2b2ae35)
  const creak = resonator(9)
  const groan = resonator(3.2)
  const samples = render(SWING_MS, (t, u) => {
    const n = rnd()
    // Slipping fibres: a fast irregular tremolo, deep but never to zero.
    const flutter = 0.55 + (0.45 * Math.sin(t * 96) * Math.sin(t * 37))
    // Arch the level so the creak swells and eases like the rope loading up at
    // the top of the arc rather than starting at full strain.
    const env = Math.sin(Math.PI * clamp01(u)) ** 1.25
    const hi = creak(n, lerp(430, 390, u)) * 2.6
    const lo = groan(n, lerp(190, 165, u)) * 1.5
    return Math.tanh(((hi * flutter) + lo) * env * 1.4) *
      fadeEnds(u, 20, 60, SWING_MS)
  })
  write('swing.mp3', normalise(samples, 0.7), 96)
}
